import React, { useState } from 'react';
import { Search } from 'lucide-react';

const MessagesList = ({ onSelectMessage }) => {
  const [messages] = useState([
    { id: 1, sender: 'John Doe', message: 'Bonjour, j\'ai une question concernant ma commande...', time: '10:30 AM', unread: true },
    { id: 2, sender: 'Sarah Smith', message: 'Merci pour votre aide rapide!', time: 'Hier', unread: false },
    { id: 3, sender: 'Mike Johnson', message: 'Est-ce que le produit sera disponible bientôt?', time: '2 jours', unread: true },
  ]);

  const [search, setSearch] = useState('');

  const filteredMessages = messages.filter(msg =>
    msg.sender.toLowerCase().includes(search.toLowerCase()) ||
    msg.message.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="bg-gradient-to-br from-white to-white/70 dark:from-neutral-900 dark:to-neutral-900/70 backdrop-blur-xl rounded-xl md:rounded-2xl shadow-lg border border-white/30 dark:border-neutral-800/50 h-full">
      <div className="p-3 md:p-4 border-b border-neutral-200 dark:border-neutral-700">
        <div className="relative">
          <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
            <Search className="h-4 w-4 text-neutral-400" />
          </div>
          <input
            type="search"
            placeholder="Rechercher..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="pl-10 pr-4 py-2 w-full rounded-xl border border-neutral-200 dark:border-neutral-700 bg-white/50 dark:bg-neutral-800/50 text-neutral-900 dark:text-white placeholder-neutral-500 focus:outline-none focus:ring-2 focus:ring-primary-500/20 focus:border-primary-500 transition-all text-sm md:text-base"
          />
        </div>
      </div>
      <div className="max-h-[400px] md:max-h-[500px] overflow-y-auto">
        {filteredMessages.map((msg) => (
          <div 
            key={msg.id} 
            onClick={() => onSelectMessage(msg)}
            className={`p-3 md:p-4 border-b border-neutral-100 dark:border-neutral-800/50 hover:bg-neutral-50 dark:hover:bg-neutral-800/30 cursor-pointer transition-colors ${msg.unread ? 'bg-primary-50 dark:bg-primary-900/10' : ''}`}
          >
            <div className="flex items-center space-x-3">
              <div className="h-8 w-8 md:h-10 md:w-10 rounded-full bg-gradient-to-r from-primary-500 to-accent-500 flex items-center justify-center flex-shrink-0">
                <span className="text-white font-medium text-sm md:text-base">{msg.sender.charAt(0)}</span>
              </div>
              <div className="flex-1 min-w-0">
                <div className="flex items-center justify-between">
                  <p className={`font-medium text-sm md:text-base ${msg.unread ? 'text-neutral-900 dark:text-white' : 'text-neutral-700 dark:text-neutral-300'} truncate`}>
                    {msg.sender}
                  </p>
                  <span className="text-xs text-neutral-500 dark:text-neutral-500">{msg.time}</span>
                </div>
                <p className="text-xs md:text-sm text-neutral-600 dark:text-neutral-400 truncate">{msg.message}</p>
              </div>
              {msg.unread && (
                <span className="h-2 w-2 bg-primary-500 rounded-full flex-shrink-0"></span>
              )}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default MessagesList;
